import{describe,it,expect}from"vitest";describe("quizQuestions — food quiz data integrity",()=>{it("has exactly 8 questions",()=>{expect(quizQuestions).toHaveLength(8)}),it("each question has all required fields",()=>{quizQuestions.forEach(e=>{expect(e).toHaveProperty("question"),expect(e).toHaveProperty("options"),expect(e).toHaveProperty("answer")})}),it("each question has exactly 4 options",()=>{quizQuestions.forEach(e=>{expect(Array.isArray(e.options)).toBe(!0),expect(e.options).toHaveLength(4)})}),it("each answer is one of the options for that question",()=>{quizQuestions.forEach(e=>{expect(e.options).toContain(e.answer)})}),it("every question string is non-empty",()=>{quizQuestions.forEach(e=>{expect(typeof e.question).toBe("string"),expect(e.question.trim().length).toBeGreaterThan(0)})}),it("every option string is non-empty",()=>{quizQuestions.forEach(e=>{e.options.forEach(e=>{expect(typeof e).toBe("string"),expect(e.trim().length).toBeGreaterThan(0)})})}),it("all options within a question are unique",()=>{quizQuestions.forEach(e=>{expect(new Set(e.options).size).toBe(e.options.length)})}),it("no two questions are identical",()=>{const e=quizQuestions.map(e=>e.question);expect(new Set(e).size).toBe(e.length)})});